    "slug": "guess-the-elo-chess-exercise",
    "title": "Guess the Elo as a chess observation exercise",
    "description": "Use Guess the Elo to notice decision quality, recurring errors and uncertainty, without treating a single game as proof of a player’s strength.",
    "keyword": "guess the Elo chess training",
    "cluster": "study-plans",
    "lede": "Use Guess the Elo to notice decision quality, recurring errors and uncertainty, without treating a single game as proof of a player’s strength.",
    "sections": [
      {
        "heading": "Make a reasoned estimate, not a snap verdict",
        "paragraphs": [
          "Guess the Elo asks you to infer a level from the moves in a game. The useful exercise is not merely choosing a number. It is explaining what you observed: tactical awareness, development, clock-related errors, conversion technique or the ability to respond to threats.",
          "A single game is an incomplete sample. Players can perform above or below their usual level, and ratings belong to particular systems and time controls. Avoid equating one conspicuous blunder with a precise rating, or assuming a polished opening proves strong play in every phase."
        ]
      },
      {
        "heading": "Watch for repeated decisions",
        "paragraphs": [
          "Pause after a few moves and record an initial impression. Then look for patterns rather than isolated events. Does a player repeatedly leave pieces undefended? Do both sides coordinate their pieces? Are pawn breaks connected to a plan, or do they create weaknesses without a clear purpose?",
          "Change your estimate when later evidence challenges it. A player may know an opening sequence but mishandle the resulting middlegame; another may make an early mistake and defend resourcefully afterwards. Updating a judgement is part of the exercise. The goal is to explain why the evidence changed, not protect your first guess."
        ]
      },
      {
        "heading": "Separate difficulty from apparent accuracy",
        "paragraphs": [
          "A simple position can allow many reasonable moves, while a complicated attack can demand a unique defence. When assessing a player’s choices, ask how difficult the decisions were. A sequence of obvious recaptures does not supply the same evidence as finding a quiet defensive move under pressure.",
          "If you consult an engine after watching, use it to inspect specific decisions. Do not convert an accuracy percentage into a personal rating. Analysis methods differ, and a game-wide score can hide both brilliant resources and simple mistakes. Your written observations should remain connected to the board rather than a formula you cannot justify."
        ]
      },
      {
        "heading": "Finish with a lesson for your own play",
        "paragraphs": [
          "After the rating is revealed, compare your reasons with the game. Which feature did you overweight? Perhaps you judged the entire game from an opening mistake or underestimated careful defensive moves. Choose one decision to analyse as if you had been playing it yourself.",
          "Then attempt a related position without being told the expected level. This transfers the activity from guessing other players' ratings to recognising practical chess features. Do not use a guessed level to mock a player or allege cheating. Treat the game as limited evidence and the exercise as a prompt for careful observation. Its value lies in sharpening what you notice and how honestly you handle uncertainty, not in claiming a reliable rating detector."
        ]
      }
    ],
