    "slug": "overloaded-defender-duties",
    "title": "Find an overloaded defender by listing its jobs",
    "description": "Find overloaded defenders by listing incompatible duties, checking alternative defenders and calculating sacrifice refusals.",
    "keyword": "overloaded defender chess",
    "cluster": "tactics",
    "lede": "An overloaded defender appears busy, but the tactic depends on incompatible duties. Train yourself to list those duties and prove that the piece cannot satisfy both after a forcing move.",
    "sections": [
      {
        "heading": "Write duties as concrete dependencies",
        "paragraphs": [
          "Choose an opposing piece that guards two important points. Describe each job precisely: protecting a rook, preventing a mating move, blocking an open file, or supporting a pawn's recapture. 'It defends the kingside' is too vague to calculate.",
          "Two duties do not automatically mean overload. The defender may meet both threats with one capture or move, or another piece may take over one job. The test is whether your forcing move makes the duties conflict in a specific legal continuation."
        ]
      },
      {
        "heading": "Choose which duty to challenge first",
        "paragraphs": [
          "Try threatening the job that demands the most immediate response. A mating threat can make a material duty impossible to maintain. A forcing capture may compel the defender to leave a critical square. Compare the move orders rather than assuming either order wins.",
          "After the defender moves, recount the remaining protection. An apparent overloaded rook may have been guarding a piece that the king can also defend. The combination needs the dependency that actually disappears, not the one that looks impressive in a diagram."
        ]
      },
      {
        "heading": "Review the failed defence, not only the sacrifice",
        "paragraphs": [
          "When a solution involves a sacrifice, write why declining it fails. If the opponent can safely refuse, the idea may be a speculative attack rather than a forced overload. A puzzle's intended solution does not remove your obligation to test alternatives.",
          "For prevention, look at your own pieces before choosing an active move. If one queen is your only answer to mate and also protects loose material, moving another defender away can create the combination for your opponent. Reducing duties can be better than adding another attack."
        ]
      },
      {
        "heading": "Update defensive duties after exchanges",
        "paragraphs": [
          "Include your own defensive pieces in the audit after every exchange. A queen doing one job may acquire a second when a rook disappears. Likewise, exchanging an attacking bishop can relieve an overload without winning material immediately. Distinguish a permanent structural burden from a temporary tactical conflict. The first suggests a longer plan; the second may require action now. Your opponent may otherwise reorganise or provide a replacement defender, making a previously promising combination disappear before you have a chance to use it."
        ]
      },
      {
        "heading": "Build a two-duty table for the defender",
        "paragraphs": [
          "Take six positions with several defensive pieces. Before solving, create a two-row duty table for the suspected defender. Predict which job it must abandon after your candidate move.",
          "Then check the strongest refusal and the strongest acceptance of any sacrifice. Mark a solution complete only when you can explain both. On a later day, revisit one example from the defender's perspective and choose a quiet move that would have removed the overload before the tactic became available."
        ]
      }
    ],
