    "lede": "Removing a defender is a move-order problem. Capturing the protector first may expose the target, but changing the order can lose a tempo, open a counterattack or leave the material count unchanged.",
    "sections": [
      {
        "heading": "Map the defender and the actual target",
        "paragraphs": [
          "Select the piece you want to win, then identify what protects it. If several pieces defend it, removing only one may accomplish nothing. Count legal recaptures rather than simply counting nearby pieces; pinned defenders and blocked lines require individual checking.",
          "Next identify what your first capture gives up. Sacrificing a bishop to remove a pawn that guards another bishop might only exchange equal material. A useful tactic has a concrete payoff after the entire sequence, including the opponent's strongest reply."
        ]
      },
      {
        "heading": "Compare both capture orders",
        "paragraphs": [
          "Calculate 'defender first, target second' and 'target first, defender second' where both are legal. Note which order includes check, which allows an intermediate move, and which changes the line of a rook or bishop. The forcing order is not always the capture with the largest immediate value.",
          "Do not assume the opponent must recapture your first sacrifice. If your piece can remain attacked while they create a stronger threat, the removal plan needs a response to that threat. A sequence is only forced when alternatives are accounted for."
        ]
      },
      {
        "heading": "Recount after every exchange",
        "paragraphs": [
          "A removed defender may reveal a second defender behind it. A recapturing pawn can open a rook's file. These changes are why a static attacker-versus-defender count is only a starting point. Update the board in your mind after each move.",
          "For defence, ask whether your most important piece is protected only once and whether that sole protector can be traded off with tempo. Adding a second defender, exchanging the attacking piece, or moving the target can all break the dependency before material is lost."
        ]
      },
      {
        "heading": "Why the checking capture order may be wrong",
        "paragraphs": [
          "A checking capture of the defender narrows the reply, yet not every checking order is best. The check may force the king onto a square that protects your target. Conversely, a non-checking capture can work because it threatens mate. Compare resulting defensive geometry rather than ranking orders solely by whether they give check. Your final explanation should say what protection disappears and why no useful replacement arrives in time. Include any lost tempo that makes the difference between two otherwise similar-looking capture sequences."
        ]
      },
      {
        "heading": "Compare both capture orders with a material ledger",
        "paragraphs": [
          "Solve five positions with a target protected by one critical piece. Write both candidate capture orders before moving, even if one looks obviously inferior. Explain the earliest difference between the two lines.",
          "Keep a final material ledger: pieces given, pieces won, and any remaining immediate threat. If your answer wins a queen but loses two rooks and another piece, the ledger should make that visible. Repeat failed examples until the move order, rather than the motif name, is what you remember."
        ]
      }
    ],
